#include <bits/stdc++.h>
using namespace std;

typedef pair<int,int> point;

const int MAXR = 11;
const int MAXN = 1000;
const int MAXM = 100100;
const int INF = (1<<29);

int edges[2*MAXM], flowVal[2*MAXM], cap[2*MAXM], nxtEdge[2*MAXM];
int head[MAXN], cur[MAXN], dist[MAXN], qArr[MAXN];
int ECount, NNodes, S, T, frontIdx, rearIdx;

void initFlow(int nodes, int sNode, int tNode) {
    NNodes=nodes; S=sNode; T=tNode; ECount=2;
    for (int i=0; i<=NNodes; i++) head[i]=0;
}
void addEdge(int u, int v, int c) {
    edges[ECount]=v; flowVal[ECount]=0; cap[ECount]=c; nxtEdge[ECount]=head[u]; head[u]=ECount++;
    edges[ECount]=u; flowVal[ECount]=0; cap[ECount]=0; nxtEdge[ECount]=head[v]; head[v]=ECount++;
}
bool buildLevel() {
    for (int i=0; i<=NNodes; i++) dist[i]=0;
    frontIdx=rearIdx=0;
    qArr[frontIdx++]=S;
    dist[S]=1;
    while (rearIdx<frontIdx && !dist[T]) {
        int u=qArr[rearIdx++];
        for (int e=head[u]; e; e=nxtEdge[e]) {
            int v=edges[e];
            if (!dist[v] && flowVal[e]<cap[e]) {
                dist[v]=dist[u]+1;
                qArr[frontIdx++]=v;
            }
        }
    }
    return dist[T]!=0;
}
int sendFlow(int u, int f) {
    if (u==T) return f;
    for (int &e=cur[u], fSent=0; e; e=nxtEdge[e]) {
        int v=edges[e];
        if (dist[u]<dist[v] && flowVal[e]<cap[e] && (fSent=sendFlow(v, min(f, cap[e]-flowVal[e])))) {
            flowVal[e]+=fSent;
            flowVal[e^1]-=fSent;
            return fSent;
        }
    }
    return 0;
}
int maxFlow() {
    int totalFlow=0, f;
    while (buildLevel()) {
        for (int i=0; i<=NNodes; i++) cur[i]=head[i];
        while ((f=sendFlow(S, INF))) totalFlow+=f;
    }
    return totalFlow;
}

int R;
string mazeA[MAXR], mazeB[MAXR];

int deltaX[] = {0,1,0,-1};
int deltaY[] = {1,0,-1,0};

bool canProceed(int i, int j) {
    return (i>=0 && j>=0 && i<R && j<R && mazeA[i][j]!='Y' && mazeA[i][j]!='Z');
}

int timeMap[2][MAXR][MAXR];

void performBFS(int i, int j, int c) {
    for (int k=0; k<R; k++) {
        for (int l=0; l<R; l++) {
            timeMap[c][k][l]=0;
        }
    }
    timeMap[c][i][j]=1;
    queue<point> q;
    q.push({i,j});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        if (c==1 && (timeMap[0][x][y] && timeMap[0][x][y]<=timeMap[1][x][y])) continue;
        for (int k=0; k<4; k++) {
            int nx=x+deltaX[k], ny=y+deltaY[k];
            if (canProceed(nx, ny) && !timeMap[c][nx][ny]) {
                timeMap[c][nx][ny]=timeMap[c][x][y]+1;
                q.push({nx, ny});
            }
        }
    }
}

int nodeIDMap[2][MAXR][MAXR];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T; cin >> R >> T;
    int zi=0, zj=0;
    int totalNodes=0, start=0, end=0;
    for (int i=0; i<R; i++) {
        cin >> mazeA[i];
        for (int j=0; j<R; j++) {
            if (mazeA[i][j]=='Z') {
                zi=i; zj=j;
            } else if (mazeA[i][j]!='Y') {
                totalNodes++;
                nodeIDMap[0][i][j]=totalNodes;
            }
        }
    }
    for (int i=0; i<R; i++) {
        cin >> mazeB[i];
        for (int j=0; j<R; j++) {
            if (mazeB[i][j]!='Y' && mazeB[i][j]!='Z') {
                totalNodes++;
                nodeIDMap[1][i][j]=totalNodes;
            }
        }
    }
    totalNodes++;
    start=0; end=totalNodes;
    setupFlow(totalNodes, start, end);
    for (int i=0; i<R; i++) {
        for (int j=0; j<R; j++) {
            if (mazeA[i][j]!='Z' && mazeA[i][j]!='Y') {
                addFlowEdge(start, nodeIDMap[0][i][j], mazeA[i][j]-'0');
                addFlowEdge(nodeIDMap[1][i][j], end, mazeB[i][j]-'0');
            }
        }
    }
    performBFS(zi, zj, 0);
    for (int i=0; i<R; i++) {
        for (int j=0; j<R; j++) {
            if (mazeA[i][j]>'0' && mazeA[i][j]<='9') {
                performBFS(i, j, 1);
                for (int ii=0; ii<R; ii++) {
                    for (int jj=0; jj<R; jj++) {
                        if (mazeB[ii][jj]>'0' && mazeB[ii][jj]<='9') {
                            if (timeMap[1][ii][jj] && (!timeMap[0][ii][jj] || timeMap[0][ii][jj]>=timeMap[1][ii][jj]) && timeMap[1][ii][jj]-1<=T) {
                                addFlowEdge(nodeIDMap[0][i][j], nodeIDMap[1][ii][jj], INF);
                            }
                        }
                    }
                }
            }
        }
    }
    cout << maxFlow() << '\n';
}
